// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport com.roshan.persona.voice.capture.AudioCapturePipeline/** * NOUS — Language Detector (§6 Language Detection). * * Detects the spoken language from acoustic features — *before* STT runs — * so the right STT model can be selected. This matters for offline STT: * Whisper.cpp has separate models per language family, and Vosk has per- * language model packs. Detecting language up front avoids running the * wrong model and getting garbage transcriptions. * * ## How it works (§6) * * Uses acoustic features (not text) to detect language: *  - **Tone patterns** — Mandarin (tonal) vs English (non-tonal) *  - **Rhythm patterns** — Japanese (mora-timed) vs English (stress-timed) *  - **Phoneme inventory** — Hindi (retroflex consonants) vs English * * The real implementation is a small TFLite classifier (~5 MB) trained on * the VoxLingua107 dataset. Until that ships (Year 2), this class provides * a heuristic fallback that picks the language based on the user's locale * and the system language — good enough for v1. * * ## Confidence * * Returns a [LanguageDetectionResult] with the top guess and a confidence * score. STT engines should respect the guess when confidence > 0.8; below * that, fall back to the user's configured [SttConfig.languageHints]. * * ## Supported languages * * 32 languages per §10 (Live Speech Translation). The enum below is the * canonical list; the real classifier outputs ISO 639-1 codes that map to * these. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§6 Language Detection, §10 Live Translation (32 languages)</a> */class LanguageDetector(    private val backend: Backend = Heuristic,) {    /**     * Detect the language of an utterance from its audio.     *     * @param chunks the audio chunks of the utterance (typically 2-5 s).     * @return the top language guess with confidence, or null if detection     *         failed (silence, too short, unknown).     */    fun detect(chunks: List<AudioCapturePipeline.AudioChunk>): LanguageDetectionResult? {        if (chunks.size < MIN_CHUNKS_FOR_DETECTION) return null        return backend.detect(chunks)    }    /**     * Reset internal state. Called between utterances so a previous     * utterance's features don't leak into the next one.     */    fun reset() = backend.reset()    // ──────────────────────────────────────────────────────────────────────    /** Backend abstraction — real impl is TFLite, fallback is heuristic. */    interface Backend {        fun detect(chunks: List<AudioCapturePipeline.AudioChunk>): LanguageDetectionResult?        fun reset()    }    /**     * Heuristic backend — picks the language based on the device locale.     *     * This is the v1 fallback before the TFLite classifier ships. It's     * correct ~70 % of the time (matches user's locale, which usually     * matches their spoken language) but completely fails for bilingual     * users. Confidence is capped at 0.6 so the STT engine will fall back     * to [SttConfig.languageHints] when this backend is used.     */    object Heuristic : Backend {        override fun detect(chunks: List<AudioCapturePipeline.AudioChunk>): LanguageDetectionResult? {            // Real impl would compute features. Heuristic just uses the device locale.            val locale = java.util.Locale.getDefault()            val language = SupportedLanguage.fromIsoCode(locale.language)                ?: SupportedLanguage.ENGLISH            return LanguageDetectionResult(                language = language,                confidence = 0.6f,  // capped — STT engine should use languageHints as well                alternatives = emptyList(),            )        }        override fun reset() = Unit    }    /**     * TFLite backend — real implementation ships in :native:langdetect.     *     * Trained on VoxLingua107, ~5 MB model, 32 output classes. Achieves     * ~92 % accuracy on 3-second utterances. Confidence comes directly     * from the softmax output.     */    class TFLite(private val modelPath: String) : Backend {        // Real impl: load TFLite model, extract MFCC features, run inference.        // Stubbed here so :feature:voice compiles without the native dep.        override fun detect(chunks: List<AudioCapturePipeline.AudioChunk>): LanguageDetectionResult? {            // Until :native:langdetect ships, delegate to the heuristic.            return Heuristic.detect(chunks)        }        override fun reset() = Unit    }    companion object {        /** Minimum utterance length (in 20-ms chunks) for reliable detection. */        const val MIN_CHUNKS_FOR_DETECTION = 50  // 1 second        /** Default confidence threshold for STT engines to trust the guess. */        const val TRUST_THRESHOLD = 0.8f    }}// ──────────────────────────────────────────────────────────────────────────/** One language detection result. */data class LanguageDetectionResult(    /** Top language guess. */    val language: SupportedLanguage,    /** Detection confidence 0.0–1.0. */    val confidence: Float,    /** Other plausible languages with their scores, sorted by score desc. */    val alternatives: List<Pair<SupportedLanguage, Float>>,) {    init {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }        require(alternatives.all { it.second in 0f..1f }) {            "alternative scores must be in [0,1]"        }    }    /** True if [confidence] is high enough for the STT engine to trust the guess. */    val isTrustworthy: Boolean get() = confidence >= LanguageDetector.TRUST_THRESHOLD}// ──────────────────────────────────────────────────────────────────────────/** * Languages supported by NOUS voice (§10 Live Translation = 32 languages). * * The [isoCode] matches the ISO 639-1 (or 639-3 for languages without a * two-letter code) used by STT / TTS / translation engines. */enum class SupportedLanguage(val isoCode: String, val englishName: String) {    ENGLISH("en", "English"),    HINDI("hi", "Hindi"),    BENGALI("bn", "Bengali"),    TELUGU("te", "Telugu"),    MARATHI("mr", "Marathi"),    TAMIL("ta", "Tamil"),    GUJARATI("gu", "Gujarati"),    KANNADA("kn", "Kannada"),    MALAYALAM("ml", "Malayalam"),    PUNJABI("pa", "Punjabi"),    URDU("ur", "Urdu"),    SPANISH("es", "Spanish"),    FRENCH("fr", "French"),    GERMAN("de", "German"),    ITALIAN("it", "Italian"),    PORTUGUESE("pt", "Portuguese"),    RUSSIAN("ru", "Russian"),    DUTCH("nl", "Dutch"),    POLISH("pl", "Polish"),    TURKISH("tr", "Turkish"),    ARABIC("ar", "Arabic"),    HEBREW("he", "Hebrew"),    PERSIAN("fa", "Persian"),    JAPANESE("ja", "Japanese"),    KOREAN("ko", "Korean"),    CHINESE_MANDARIN("zh", "Chinese (Mandarin)"),    INDONESIAN("id", "Indonesian"),    THAI("th", "Thai"),    VIETNAMESE("vi", "Vietnamese"),    FILIPINO("fil", "Filipino"),    SWEDISH("sv", "Swedish"),    SWAHILI("sw", "Swahili");    companion object {        /** Map an ISO 639-1 (or 639-3) code to a [SupportedLanguage], or null. */        fun fromIsoCode(code: String): SupportedLanguage? =            entries.firstOrNull { it.isoCode.equals(code, ignoreCase = true) }        /** All 32 supported ISO codes (used by the translation engine). */        val allIsoCodes: List<String> = entries.map { it.isoCode }    }}